INSERT INTO private.ielts_learning_tasks (code, title, purpose, audio_path, audio_sha256, taxonomy_version_id, pilot_student, version, skill, instructions, success_description, questions, content, requires_review, review_record, content_sha256) VALUES
('bh-ielts-targeted-listening-l3-v1', 'Book the final arrangement: pottery workshop', 'guided_practice', 'extension-pack-02/051a7be84978ff4b530dfb1dbf47f2b2945b73e64204366bd4d39d1d7e090d4e/L3_practice_v1.mp3', '051a7be84978ff4b530dfb1dbf47f2b2945b73e64204366bd4d39d1d7e090d4e', 'd4ad52b6-fd0f-4068-9982-28b89ff389c5', 'b30e9c28-96f1-4d34-83e9-9b28b4926f42', '0.1.0', 'listening', 'Complete all six answers. Write no more than TWO WORDS AND/OR A NUMBER for each answer. Listen for the final confirmed details. You may pause or replay for practice. Gentle phone tonal colour on the receptionist. No added noise, dropouts or masked words. Internal guided-practice adaptation, not an official IELTS recording condition.', 'Identify the final confirmed detail after a speaker changes an earlier suggestion.', '[{"id":"q1","prompt":"Workshop day","accepted_answers":["Saturday"],"taxonomy_node_id":"0dbe1c8f-403a-493f-afd3-c219310fb18a","supporting_node_id":"f9064b63-e3f1-4bfa-8e8e-97a02756afb2"},{"id":"q2","prompt":"Starting time","accepted_answers":["9:40","09:40","9.40","nine forty"],"taxonomy_node_id":"0dbe1c8f-403a-493f-afd3-c219310fb18a","supporting_node_id":"f9064b63-e3f1-4bfa-8e8e-97a02756afb2"},{"id":"q3","prompt":"Student fee (£)","accepted_answers":["14","fourteen"],"taxonomy_node_id":"d5b1fddb-ba6f-4be1-8513-bb26d822357a","supporting_node_id":"f9064b63-e3f1-4bfa-8e8e-97a02756afb2"},{"id":"q4","prompt":"Entrance to use","accepted_answers":["west gate"],"taxonomy_node_id":"d0aa0bad-ecfa-4598-8f2f-07e93d3fa59b","supporting_node_id":"f9064b63-e3f1-4bfa-8e8e-97a02756afb2"},{"id":"q5","prompt":"Bring a","accepted_answers":["sketchbook"],"taxonomy_node_id":"d0aa0bad-ecfa-4598-8f2f-07e93d3fa59b","supporting_node_id":"f9064b63-e3f1-4bfa-8e8e-97a02756afb2"},{"id":"q6","prompt":"Maximum group size","accepted_answers":["16","sixteen"],"taxonomy_node_id":"d5b1fddb-ba6f-4be1-8513-bb26d822357a","supporting_node_id":"f9064b63-e3f1-4bfa-8e8e-97a02756afb2"}]'::jsonb, '{"scope":"Original IELTS-style guided Listening practice; not an official IELTS recording or a band assessment.","teacher_notes":"Gentle phone tonal colour on the receptionist. No added noise, dropouts or masked words. Internal guided-practice adaptation, not an official IELTS recording condition.\n\nTranscript:\nReceptionist: Good morning, Bellmere Arts Centre. How can I help?\nCaller: Hello. I''d like to book the beginner pottery workshop. The leaflet says Sunday. Is that still right?\nReceptionist: That was the original plan, but the tutor is away on Sunday. We''ve moved it to Saturday. The website now has the correct day.\nCaller: Saturday suits me. I finish work early that morning. Does it still start at ten?\nReceptionist: A little earlier, actually. We need time to prepare the clay, so the workshop begins at nine forty. Please be ready then; ten o''clock is when the first demonstration ends.\nCaller: I''ll make a note. And is the fee eighteen pounds, as advertised? I''m a student.\nReceptionist: Eighteen is the standard fee. With a current student card, you''ll pay fourteen pounds. That includes the clay and firing your finished piece.\nCaller: Lovely. I''ve been to the centre before. Shall I come through the main entrance?\nReceptionist: There''s a market outside it that morning. Use the west gate instead. A volunteer there will direct you to the studio.\nCaller: Do I need to bring an apron, or any tools?\nReceptionist: We supply those. Bring a sketchbook so you can draw ideas for your piece. You don''t need to buy any special equipment.\nCaller: My classmate might come too. The leaflet mentions twenty places. Are there still spaces?\nReceptionist: There are spaces, yes, but we''ve reduced the group to sixteen so everyone gets enough help. That is the maximum now. I can reserve two places if your classmate confirms today.\nCaller: I''ll check with her and call back. Thanks for explaining everything.\nReceptionist: You''re welcome. We look forward to seeing you.\n\nKey and teaching notes:\nq1: Saturday. Sunday was the original plan; the workshop has moved to Saturday. Primary: Dates and times; supporting: Distractor resistance.\nq2: 9:40 / 09:40 / 9.40 / nine forty. The start is nine forty. Ten is when the demonstration ends. Primary: Dates and times; supporting: Distractor resistance.\nq3: 14 / fourteen. Eighteen is the standard fee; fourteen applies to a student with a current card. Primary: Numerical information; supporting: Distractor resistance.\nq4: west gate. The receptionist says to use the west gate instead of the main entrance. Primary: Explicit detail; supporting: Distractor resistance.\nq5: sketchbook. An apron and tools are supplied. The caller should bring a sketchbook. Primary: Explicit detail; supporting: Distractor resistance.\nq6: 16 / sixteen. Twenty was printed on the leaflet; the maximum has been reduced to sixteen. Primary: Numerical information; supporting: Distractor resistance."}'::jsonb, true, '{"audio_approval":{"reviewer":"Sobbi (Brains Heist owner)","date":"2026-10-09","source_statement":"Listened and approved","scope":"Approval of the two delivered practice recordings. Teacher confirmation of editorial quality, keys, mappings, difficulty/timing and originality remains required for assignment. No calibration, device, capacity or wider-release approval inferred.","files":[{"file":"L3_practice_v1.mp3","sha256":"051a7be84978ff4b530dfb1dbf47f2b2945b73e64204366bd4d39d1d7e090d4e"},{"file":"L4_practice_v1.mp3","sha256":"df4c58e67b9778d30d7a77399a392e9a417670b36e8a557da73c560f6ec394d5"}]},"draft_reference":"docs/ielts/practice/LISTENING_EXTENSION_02_DRAFT.json","draft_content_sha256":"427a854a48eaa39882d6e35d8c5b8009c8b7d3a4725a1aef113dbd561e861279","script_sha256":"5b066444324ea8f3355856975935aa5ab1d2dda4f838cb4a79ba95e9cab398be","voices":{"Caller":"James","Receptionist":"Paula"},"provider":"ElevenLabs","model":"eleven_multilingual_v2","copyright_intro":"This recording is copyright Brains Heist LLC. All rights reserved."