2.235,"end_seconds":132.585},{"segment":"L4_11","start_seconds":132.585,"end_seconds":140.851},{"segment":"turn_gap","start_seconds":140.851,"end_seconds":141.201},{"segment":"L4_12","start_seconds":141.201,"end_seconds":148.074},{"segment":"turn_gap","start_seconds":148.074,"end_seconds":148.424},{"segment":"L4_13","start_seconds":148.424,"end_seconds":153.254},{"segment":"turn_gap","start_seconds":153.254,"end_seconds":153.604},{"segment":"response","start_seconds":153.604,"end_seconds":156.576},{"segment":"response_silence","start_seconds":156.576,"end_seconds":171.576},{"segment":"end","start_seconds":171.576,"end_seconds":174.037},{"segment":"tail","start_seconds":174.037,"end_seconds":174.337}],"human_review":"Owner listened and approved, 2026-10-09; exact-file audio scope.","encoded_verification":{"detected_pauses":[{"label":"reading_silence","detected_start":23.9527,"detected_end":54.2436,"detected_seconds":30.291},{"label":"response_silence","detected_start":156.407,"detected_end":171.601,"detected_seconds":15.194}],"decoded_peak_dbfs":-3.32,"decoded_clipped_samples":0,"decoded_seconds":174.337,"sha256_rechecked":true}},"installation_verified":"2026-10-09","teacher_content_review":"Required before assignment; no teacher confirmation recorded by installation."}'::jsonb, 'df8a0c8ebc957e5fbb2e5ea60162fd0d0f1d6bc773de440131fcad82dcef381b');
